        {
            "activity_id": "A4",
            "activity_name": "U4: Backport Kafka Health Checks",
            "activity_description": "Identify the relevant commit(s) from master. Merge or cherry-pick into the release-1.4 branch. Resolve any conflicts. Run the integration test suite for ordering service with Kafka.",
